foreach(string mode in new[]{"ok","error","cancel"})
{
    try
    {
        using var first=new Resource(mode+":first");
        using var second=new Resource(mode+":second");
        if(mode=="error")throw new InvalidOperationException("demo");
        if(mode=="cancel")throw new OperationCanceledException();
        Console.WriteLine("ok:work");
    }
    catch(OperationCanceledException){Console.WriteLine("canceled");}
    catch(InvalidOperationException){Console.WriteLine("failed");}
}
class Resource(string name):IDisposable
{ public void Dispose()=>Console.WriteLine("dispose "+name); }

